using System.ComponentModel;
using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;

namespace ResearchAgent;

/// <summary>
/// Provides web search capabilities to the AI agent.
/// Uses the Google Custom Search JSON API when configured,
/// otherwise falls back to a built-in stub for demonstration.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _http = new();
    private readonly string? _apiKey;
    private readonly string? _searchEngineId;

    public WebSearchTool()
    {
        _apiKey = Environment.GetEnvironmentVariable("GOOGLE_SEARCH_API_KEY");
        _searchEngineId = Environment.GetEnvironmentVariable("GOOGLE_SEARCH_ENGINE_ID");
    }

    [Description("Search the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrEmpty(_apiKey) && !string.IsNullOrEmpty(_searchEngineId))
        {
            return await SearchGoogleAsync(query, maxResults);
        }

        return GetStubResults(query);
    }

    private async Task<string> SearchGoogleAsync(string query, int maxResults)
    {
        var url = $"https://www.googleapis.com/customsearch/v1"
                + $"?key={_apiKey}&cx={_searchEngineId}"
                + $"&q={WebUtility.UrlEncode(query)}&num={maxResults}";

        try
        {
            var json = await _http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);

            var results = new List<object>();
            if (doc.RootElement.TryGetProperty("items", out var items))
            {
                foreach (var item in items.EnumerateArray())
                {
                    results.Add(new
                    {
                        title = item.GetProperty("title").GetString(),
                        snippet = item.GetProperty("snippet").GetString(),
                        url = item.GetProperty("link").GetString()
                    });
                }
            }

            return results.Count > 0
                ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
                : "No results found.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string GetStubResults(string query)
    {
        // Provide realistic-looking stub results for demonstration
        var sanitized = Regex.Replace(query, @"[^\w\s]", "").Trim();
        var results = new[]
        {
            new
            {
                title = $"{sanitized} - Wikipedia",
                snippet = $"A comprehensive overview of {sanitized.ToLowerInvariant()}. This article covers history, key concepts, recent developments, and future outlook.",
                url = $"https://en.wikipedia.org/wiki/{WebUtility.UrlEncode(sanitized.Replace(' ', '_'))}"
            },
            new
            {
                title = $"Latest Research on {sanitized}",
                snippet = $"Recent studies and breakthroughs related to {sanitized.ToLowerInvariant()} published in leading journals. Experts highlight significant progress.",
                url = $"https://example.com/research/{WebUtility.UrlEncode(sanitized.ToLowerInvariant())}"
            },
            new
            {
                title = $"{sanitized}: A Practical Guide",
                snippet = $"An in-depth practical guide covering the fundamentals and advanced topics of {sanitized.ToLowerInvariant()} for practitioners and enthusiasts.",
                url = $"https://example.com/guides/{WebUtility.UrlEncode(sanitized.ToLowerInvariant())}"
            }
        };

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capabilities for the AI agent to organise
/// findings during research before producing a final summary.
/// </summary>
public sealed class NotepadTool
{
    private readonly List<Note> _notes = [];

    public sealed record Note(string Topic, string Content, DateTime Timestamp);

    [Description("Save a research note. Use this to record key findings, facts, or insights discovered during research.")]
    public string AddNote(
        [Description("A short topic or heading for the note")] string topic,
        [Description("The detailed content of the note")] string content)
    {
        _notes.Add(new Note(topic, content, DateTime.UtcNow));
        return $"Note #{_notes.Count} saved under topic \"{topic}\".";
    }

    [Description("Retrieve all saved research notes. Use this to review collected information before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var lines = _notes.Select((n, i) =>
            $"--- Note #{i + 1}: {n.Topic} ---\n{n.Content}");

        return string.Join("\n\n", lines);
    }

    [Description("Get the total number of notes currently saved.")]
    public string GetNoteCount()
    {
        return $"{_notes.Count} note(s) saved.";
    }
}

