using System.ClientModel;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model  = Environment.GetEnvironmentVariable("OPENAI_MODEL")   ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("ERROR: Set the OPENAI_API_KEY environment variable.");
    return 1;
}

// ---------------------------------------------------------------------------
// Build tools from the helper classes
// ---------------------------------------------------------------------------
var searchTool  = new WebSearchTool();
var notepadTool = new NotepadTool();

var tools = new AIFunctionFactory[]
    { }            // placeholder – we populate the list below
    .ToList();     // unused; see chatTools

List<AITool> chatTools =
[
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(notepadTool.AddNote),
    AIFunctionFactory.Create(notepadTool.GetNotes),
    AIFunctionFactory.Create(notepadTool.GetNoteCount),
];

// ---------------------------------------------------------------------------
// Build the chat client with automatic function-calling
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = chatTools };

// ---------------------------------------------------------------------------
// System prompt that instructs the agent how to behave
// ---------------------------------------------------------------------------
const string SystemPrompt = """
    You are a Research Agent. Your job is to thoroughly research a topic the
    user provides, then deliver a well-structured summary.

    You have two sets of tools:

    1. **Web Search** – use `SearchWebAsync` to find information online.
       Make multiple searches with different queries to get broad coverage.

    2. **Notepad** – use `AddNote` to save important findings as you go,
       and `GetNotes` / `GetNoteCount` to review what you have collected.

    ## Workflow
    1. Receive a research topic from the user.
    2. Search the web with several varied queries related to the topic.
    3. For each useful result, save a note capturing the key facts.
    4. After gathering enough information (at least 3-5 notes), retrieve
       all notes and synthesize them into a clear, well-organized summary.
    5. Present the final summary to the user with sections, bullet points,
       and source URLs where available.

    Always think step-by-step and explain what you are doing.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════════╗");
Console.WriteLine("║          🔍  AI Research Agent  🔍          ║");
Console.WriteLine("╠══════════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit' to    ║");
Console.WriteLine("║  exit. The agent will search the web, take   ║");
Console.WriteLine("║  notes, and produce a summary.               ║");
Console.WriteLine("╚══════════════════════════════════════════════╝");

if (!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("GOOGLE_SEARCH_API_KEY")))
    Console.WriteLine("  [Google Search API configured ✓]");
else
    Console.WriteLine("  [Using stub search results – set GOOGLE_SEARCH_API_KEY for live search]");

Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic))
        continue;
    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase) ||
        topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    // Start a fresh conversation per topic
    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary:\n\n{topic}"),
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching… (the agent will search & take notes automatically)\n");
    Console.ResetColor();

    try
    {
        var response = await client.GetResponseAsync(messages, chatOptions);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══════════════════ Research Summary ═══════════════════");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("═══════════════════════════════════════════════════════\n");
        Console.ResetColor();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Error.WriteLine($"Error: {ex.Message}\n");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");
return 0;

